package org.rabochaya.projects;
import java.io.*;import java.security.*;import java.util.*;
/** Immutable project-owned raster stack; order is bottom to top, never KML data. */
public final class MapComposition {
 public static final int MAX_LAYERS=16;private static final int MAGIC=0x524b4c59,MAX_BYTES=131072;
 public final long project;public final List<Layer> layers;
 public static final class Layer {
  public final String id,kind,key,name,template,attribution;public final boolean visible,downloads;public final int opacity,minZoom,maxZoom;
  private Layer(String id,String kind,String key,String name,String template,String attribution,int min,int max,boolean downloads,boolean visible,int opacity){
   if(id==null||!id.matches("[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}")||!Arrays.asList("catalog","custom","local","bundled").contains(kind)||key==null||key.length()>128||name==null||name.isEmpty()||name.length()>100||template==null||template.length()>2048||attribution==null||attribution.length()>500||opacity<0||opacity>100)throw new IllegalArgumentException("Недопустимый слой карты");
   if("catalog".equals(kind)){if(!key.matches("[A-Z0-9_]+")||!template.isEmpty()||!attribution.isEmpty()||min!=0||max!=0||downloads)throw new IllegalArgumentException("Недопустимый источник каталога");}
   else if("custom".equals(kind)){if(!key.isEmpty())throw new IllegalArgumentException("Недопустимый собственный источник");new TileSource(name,template,attribution,min,max,downloads);}
   else if(!key.isEmpty()||!template.isEmpty()||!attribution.isEmpty()||min!=0||max!=0||downloads)throw new IllegalArgumentException("Недопустимая локальная подложка");
   this.id=id;this.kind=kind;this.key=key;this.name=name;this.template=template;this.attribution=attribution;minZoom=min;maxZoom=max;this.downloads=downloads;this.visible=visible;this.opacity=opacity;
  }
  public static Layer catalog(String key){TileSource source=MapCatalog.find(key);if(source==null)throw new IllegalArgumentException("Источник отсутствует в каталоге");return new Layer(UUID.randomUUID().toString(),"catalog",key,source.name,"","",0,0,false,true,100);}
  public static Layer custom(TileSource source){if(source==null||source.layers!=null)throw new IllegalArgumentException("Выберите отдельный XYZ-источник");return new Layer(UUID.randomUUID().toString(),"custom","",source.name,source.template,source.attribution,source.minZoom,source.maxZoom,source.downloads,true,100);}
  public static Layer local(){return new Layer(UUID.randomUUID().toString(),"local","","Локальная карта MBTiles","","",0,0,false,true,100);}
  public static Layer bundled(){return new Layer(UUID.randomUUID().toString(),"bundled","","Обзорная карта","","",0,0,false,true,100);}
  public TileSource source(){return "catalog".equals(kind)?MapCatalog.find(key):"custom".equals(kind)?new TileSource(name,template,attribution,minZoom,maxZoom,downloads):null;}
  public Layer visible(boolean value){return new Layer(id,kind,key,name,template,attribution,minZoom,maxZoom,downloads,value,opacity);}
  public Layer opacity(int value){return new Layer(id,kind,key,name,template,attribution,minZoom,maxZoom,downloads,visible,value);}
 }
 public MapComposition(long project,List<Layer> layers){if(project<=0||layers==null||layers.size()>MAX_LAYERS)throw new IllegalArgumentException("Недопустимая композиция карт");Set<String> ids=new HashSet<>();ArrayList<Layer> copy=new ArrayList<>();for(Layer layer:layers){if(layer==null||!ids.add(layer.id))throw new IllegalArgumentException("Повторяющийся слой карты");copy.add(layer);}this.project=project;this.layers=Collections.unmodifiableList(copy);}
 public String attributions(){LinkedHashSet<String> values=new LinkedHashSet<>();for(Layer layer:layers)if(layer.visible&&layer.opacity>0){TileSource source=layer.source();if(source!=null)values.add(source.attribution);else if("local".equals(layer.kind)||"bundled".equals(layer.kind))values.add(layer.name);}StringBuilder text=new StringBuilder();for(String value:values){if(text.length()>0)text.append(" · ");text.append(value);}return text.toString();}
 private int index(String id){for(int i=0;i<layers.size();i++)if(layers.get(i).id.equals(id))return i;throw new IllegalArgumentException("Слой больше не найден");}
 public MapComposition add(Layer layer){ArrayList<Layer> next=new ArrayList<>(layers);next.add(layer);return new MapComposition(project,next);}
 public MapComposition remove(String id){ArrayList<Layer> next=new ArrayList<>(layers);next.remove(index(id));return new MapComposition(project,next);}
 public MapComposition move(String id,int destination){if(destination<0||destination>=layers.size())throw new IllegalArgumentException("Позиция слоя вне состава");ArrayList<Layer> next=new ArrayList<>(layers);Layer layer=next.remove(index(id));next.add(destination,layer);return new MapComposition(project,next);}
 public MapComposition visible(String id,boolean value){ArrayList<Layer> next=new ArrayList<>(layers);int i=index(id);next.set(i,next.get(i).visible(value));return new MapComposition(project,next);}
 public MapComposition opacity(String id,int value){ArrayList<Layer> next=new ArrayList<>(layers);int i=index(id);next.set(i,next.get(i).opacity(value));return new MapComposition(project,next);}
 private static byte[] digest(byte[] body){try{return MessageDigest.getInstance("SHA-256").digest(body);}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 public byte[] encode()throws IOException{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(DataOutputStream out=new DataOutputStream(bytes)){out.writeInt(MAGIC);out.writeInt(1);out.writeLong(project);out.writeInt(layers.size());for(Layer l:layers){out.writeUTF(l.id);out.writeUTF(l.kind);out.writeUTF(l.key);out.writeUTF(l.name);out.writeUTF(l.template);out.writeUTF(l.attribution);out.writeInt(l.minZoom);out.writeInt(l.maxZoom);out.writeBoolean(l.downloads);out.writeBoolean(l.visible);out.writeInt(l.opacity);}}byte[] body=bytes.toByteArray();if(body.length+32>MAX_BYTES)throw new IOException("Слишком большой состав карт");bytes.write(digest(body));return bytes.toByteArray();}
 public static MapComposition decode(byte[] all,long project)throws IOException{if(all==null||all.length<52||all.length>MAX_BYTES)throw new IOException("Недопустимый размер состава карт");byte[] body=Arrays.copyOf(all,all.length-32);if(!MessageDigest.isEqual(digest(body),Arrays.copyOfRange(all,all.length-32,all.length)))throw new IOException("Состав карт повреждён; сохранённые настройки не изменены");try(DataInputStream in=new DataInputStream(new ByteArrayInputStream(body))){if(in.readInt()!=MAGIC||in.readInt()!=1||in.readLong()!=project)throw new IOException("Состав относится к другому проекту или версии");int count=in.readInt();if(count<0||count>MAX_LAYERS)throw new IOException("Недопустимое число слоёв");List<Layer> layers=new ArrayList<>();for(int i=0;i<count;i++)layers.add(new Layer(in.readUTF(),in.readUTF(),in.readUTF(),in.readUTF(),in.readUTF(),in.readUTF(),in.readInt(),in.readInt(),in.readBoolean(),in.readBoolean(),in.readInt()));if(in.available()!=0)throw new IOException("Лишние данные состава карт");return new MapComposition(project,layers);}catch(IllegalArgumentException e){throw new IOException("Недопустимый состав карт",e);}}
}
